    "sparse_symbolic" => ["sp_add", "sp_det", "sp_det_mod", "sp_diag", "sp_dims", "sp_from_dense", "sp_identity", "sp_matmul", "sp_matvec", "sp_minpoly_mod", "sp_nnz", "sp_nullspace", "sp_rank", "sp_rank_mod", "sp_scale", "sp_solve", "sp_solve_general", "sp_solve_mod", "sp_to_dense", "sp_transpose", "sparse"],
